/*
 * A382696  Centered pentagonal numbers that are abundant.
 * https://oeis.org/A382696
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 none, u16 n <= 17, u32 n <= 44, u64 n <= 44, u128 n <= 44,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence consists of the centered pentagonal numbers
 * Cp(k) = (5*k^2 - 5*k + 2)/2 that are abundant.
 * The function a(n) returns the n‑th such number (a(1)=276).
 * It is generated by iterating over the index k, testing each Cp(k)
 * for abundance, and caching the found terms.  Subsequent calls
 * reuse the cache, so any order of requests is handled
 * efficiently.
 */
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>

/* --------------------------------------------------------------------- */
/* Prime table (generated once).  Size is chosen large enough for the
 * 10000th term.  The sieve is performed lazily in init_primes().
 */
#define PRIME_LIMIT 600000
static bool primes_ready = false;
static uint32_t *primes = NULL;
static size_t prime_count = 0;

static void init_primes(void)
{
    if (primes_ready) return;
    size_t limit = PRIME_LIMIT + 1;
    bool *is_composite = (bool *)calloc(limit, sizeof(bool));
    size_t count = 0;

    for (uint32_t i = 2; i <= PRIME_LIMIT; ++i) {
        if (!is_composite[i]) {
            ++count;
            if ((uint64_t)i * i <= PRIME_LIMIT) {
                for (uint32_t j = i * i; j <= PRIME_LIMIT; j += i)
                    is_composite[j] = true;
            }
        }
    }
    primes = (uint32_t *)malloc(count * sizeof(uint32_t));
    size_t idx = 0;
    for (uint32_t i = 2; i <= PRIME_LIMIT; ++i)
        if (!is_composite[i]) primes[idx++] = i;

    free(is_composite);
    prime_count = count;
    primes_ready = true;
}

/* --------------------------------------------------------------------- */
/* Sum of all positive divisors of n (including n).  Uses the pre‑
 * computed prime table that is large enough for the numbers we
 * will encounter.
 */
static seq_t sigma_of(seq_t n)
{
    seq_t result = 1;
    seq_t temp   = n;

    for (size_t i = 0; i < prime_count; ++i) {
        uint32_t p = primes[i];
        seq_t p_pow = 1;
        seq_t geom_sum = 1;
        /* If p^2 would exceed temp we are done with primes. */
        if ((seq_t)p * (seq_t)p > temp) break;
        if (temp % p == 0) {
            while (temp % p == 0) {
                temp /= p;
                p_pow *= p;
                geom_sum += p_pow;
            }
            result *= geom_sum;
        }
    }
    if (temp > 1) { /* remaining prime factor */
        result *= (seq_t)1 + temp;
    }
    return result;
}

/* --------------------------------------------------------------------- */
/* A number is abundant if the sum of its positive divisors exceeds 2n.
 */
static bool is_abundant(seq_t n)
{
    seq_t sigma = sigma_of(n);
    return sigma > (seq_t)2 * n;
}

/* --------------------------------------------------------------------- */
/* Cache of the produced terms.  Cached terms are appended as they are
 * found.  The array grows geometrically.
 */
static seq_t *cached_values = NULL;
static size_t cached_size   = 0;
static size_t cached_cap    = 0;
static uint64_t last_k      = 1;   /* next k to examine */

/* Ensure the cache has at least 'needed' slots. */
static void ensure_cached_cap(size_t needed)
{
    if (cached_cap >= needed) return;
    size_t new_cap = cached_cap ? cached_cap * 2 : 16;
    while (new_cap < needed) new_cap *= 2;
    seq_t *new_arr = (seq_t *)realloc(cached_values, new_cap * sizeof(seq_t));
    cached_values = new_arr;
    cached_cap = new_cap;
}

/* Generate terms until we have at least 'req' terms cached. */
static void compute_until(size_t req)
{
    ensure_cached_cap(req);
    while (cached_size < req) {
        seq_t k = (seq_t)last_k;
        seq_t pent = ((seq_t)5 * k * k - (seq_t)5 * k + (seq_t)2) / 2;
        if (is_abundant(pent)) {
            cached_values[cached_size++] = pent;
        }
        ++last_k;
    }
}

/* --------------------------------------------------------------------- */
/* Public entry point used by the OEIS framework. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;              /* undefined for the offset 0 */
    init_primes();                             /* make sure we have primes */
    compute_until((size_t)n);                  /* generate until we have n terms */
    return cached_values[(size_t)n - 1];
}
